type alien_individual = {
  lawful_permanent_resident_years : int list; (* calendar years in which individual held lawful permanent resident status at any time during the year *)
}

(* clause (i): lawfully admitted for permanent residence at any time during the calendar year *)
let is_lawful_permanent_resident (individual : alien_individual) (year : int) : bool =
  List.mem year individual.lawful_permanent_resident_years

(* clause (ii): substantial presence test of paragraph (3) *)
let meets_substantial_presence_test (individual : alien_individual) (year : int) : bool =
  (* unresolved -- needs 7701(b)(3) *)
  failwith "unresolved cross-reference"

(* clause (iii): first year election of paragraph (4) *)
let has_first_year_election (individual : alien_individual) (year : int) : bool =
  (* unresolved -- needs 7701(b)(4) *)
  failwith "unresolved cross-reference"

(* 7701(b)(1)(A): resident alien if any of (i), (ii), (iii) hold *)
let is_resident_alien (individual : alien_individual) (year : int) : bool =
  is_lawful_permanent_resident individual year ||
  meets_substantial_presence_test individual year ||
  has_first_year_election individual year

type individual_status = {
  alien : alien_individual; (* underlying alien_individual data from 7701(b)(1)(A) *)
  is_us_citizen : bool; (* whether individual is a citizen of the United States *)
}

module Alien_status = struct
  (* 7701(b)(1)(A): resident alien test, reused from sub-provision *)
  let is_resident_alien_status (individual : individual_status) (year : int) : bool =
    is_resident_alien individual.alien year

  (* 7701(b)(1)(B): nonresident alien if neither a US citizen nor a resident alien *)
  let is_nonresident_alien (individual : individual_status) (year : int) : bool =
    not individual.is_us_citizen &&
    not (is_resident_alien_status individual year)
end
